{
  "name": "Masterflex 蠕动泵",
  "name_en": "Masterflex peristaltic pump",
  "manufacturer": "Masterflex",
  "description": "一种可通过串口通信控制的实验室蠕动泵，用于连续输液、定时分配和批量加液。该设备可控制启停、转速、转向、分配模式和运行时间，并可记录体积与批次数，常用于试剂输送、流路控制和自动化液体处理。",
  "description_en": "A laboratory peristaltic pump that can be controlled through serial communication for continuous pumping, timed dispensing, and batch liquid delivery. It supports control of start/stop, speed, direction, dispense mode, and run time, and can track volume and batch counts for reagent transfer, fluid-path control, and automated liquid handling.",
  "tag_hints": [
    "peristaltic pump",
    "liquid dispensing",
    "serial communication",
    "variable speed pumping",
    "flow control",
    "batch dispensing",
    "timed dispensing"
  ],
  "actions": [
    {
      "action_name": "auto-connected",
      "description": "获取泵的串口连接状态。",
      "description_en": "Get the pump's serial connection state."
    },
    {
      "action_name": "auto-protocol",
      "description": "获取泵使用的串口通信协议。",
      "description_en": "Get the serial communication protocol used by the pump."
    },
    {
      "action_name": "auto-addr",
      "description": "获取泵的通信地址。",
      "description_en": "Get the pump communication address."
    },
    {
      "action_name": "auto-enable",
      "description": "启用泵的串口通信模式。",
      "description_en": "Enable the pump's serial communication mode."
    },
    {
      "action_name": "auto-disable",
      "description": "禁用泵的串口通信模式。",
      "description_en": "Disable the pump's serial communication mode."
    },
    {
      "action_name": "auto-status",
      "description": "获取泵的运行状态。",
      "description_en": "Get the pump operating status."
    },
    {
      "action_name": "auto-start",
      "description": "启动泵运行。",
      "description_en": "Start the pump."
    },
    {
      "action_name": "auto-stop",
      "description": "停止泵运行。",
      "description_en": "Stop the pump."
    },
    {
      "action_name": "auto-speed_percent",
      "description": "获取或设置泵速百分比。",
      "description_en": "Get or set the pump speed percentage."
    },
    {
      "action_name": "auto-set_dir",
      "description": "设置泵的转动方向。",
      "description_en": "Set the pump rotation direction."
    },
    {
      "action_name": "auto-reset_cumulative",
      "description": "将累计体积清零。",
      "description_en": "Reset the cumulative volume to zero."
    },
    {
      "action_name": "auto-set_addr",
      "description": "设置泵的通信地址。",
      "description_en": "Set the pump communication address."
    },
    {
      "action_name": "auto-speed_rpm",
      "description": "获取或设置泵速（rpm）。",
      "description_en": "Get or set the pump speed in rpm."
    },
    {
      "action_name": "auto-volume",
      "description": "获取当前单位下的体积读数。",
      "description_en": "Get the volume reading in the current unit."
    },
    {
      "action_name": "auto-volume_rev",
      "description": "获取以转数表示的体积读数。",
      "description_en": "Get the volume reading expressed in revolutions."
    },
    {
      "action_name": "auto-unit_index",
      "description": "获取或设置流量单位索引。",
      "description_en": "Get or set the flow unit index."
    },
    {
      "action_name": "auto-on_time_full",
      "description": "获取或设置完整开启时间。",
      "description_en": "Get or set the full on-time."
    },
    {
      "action_name": "auto-set_panel_active",
      "description": "设置前面板手动操作是否启用。",
      "description_en": "Set whether front-panel manual operation is enabled."
    },
    {
      "action_name": "auto-set_dispense_mode",
      "description": "设置泵的分配模式。",
      "description_en": "Set the pump dispense mode."
    },
    {
      "action_name": "auto-get_software_version",
      "description": "获取泵的软件版本。",
      "description_en": "Get the pump software version."
    },
    {
      "action_name": "auto-on_time_min",
      "description": "设置开启时间（分钟）。",
      "description_en": "Set the on-time in minutes."
    },
    {
      "action_name": "auto-on_time_hr",
      "description": "设置开启时间（小时）。",
      "description_en": "Set the on-time in hours."
    },
    {
      "action_name": "auto-get_version__model",
      "description": "获取泵的型号和串口通信版本。",
      "description_en": "Get the pump model and serial communication version."
    },
    {
      "action_name": "auto-store_configs",
      "description": "保存当前泵配置。",
      "description_en": "Store the current pump configuration."
    },
    {
      "action_name": "auto-restore_configs",
      "description": "将泵配置恢复为默认状态。",
      "description_en": "Restore the pump configuration to the default state."
    },
    {
      "action_name": "auto-reset_batch",
      "description": "将批次计数清零。",
      "description_en": "Reset the batch count to zero."
    },
    {
      "action_name": "auto-dispense_status",
      "description": "获取分配状态。",
      "description_en": "Get the dispense status."
    },
    {
      "action_name": "auto-off_time_full",
      "description": "获取或设置完整关闭时间。",
      "description_en": "Get or set the full off-time."
    },
    {
      "action_name": "auto-on_time_decisecond",
      "description": "获取或设置开启时间（十分之一秒）。",
      "description_en": "Get or set the on-time in deciseconds."
    },
    {
      "action_name": "auto-batch_count",
      "description": "获取或设置批次总数。",
      "description_en": "Get or set the total batch count."
    },
    {
      "action_name": "auto-is_valid_integer",
      "description": "校验用于泵参数设置的数值是否为有效整数。",
      "description_en": "Validate whether a value used for pump settings is a valid integer."
    }
  ]
}

